            }
            ActionButton(strip,"Effects",()=>{o.Call("_finish_automation_pass","Effects selected");Items(Session(o),"selected_ids").Clear();Session(o).Set("selected_track",master?"":track["id"].AsString());Field<TabContainer>(o,"bottom").CurrentTab=3;refresh_effects(o);});
        }
